package com.shilapi.xcertplay;
import android.content.Context;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Bounded asynchronous timestamped one-hour log, shared by reports and runtime probes. */
public final class HourDiagnosticLog {
 private static final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<Runnable>(2048),r->{Thread t=new Thread(r,"CarPlay-HourLog");t.setDaemon(true);return t;},new ThreadPoolExecutor.DiscardPolicy());
 public static void append(File dir,String text){long time=System.currentTimeMillis();worker.execute(()->{try{dir.mkdirs();File f=new File(dir,"hour-"+(time/60000)+".log");try(FileWriter w=new FileWriter(f,true)){for(String line:text.split("\\r?\\n"))w.write(time+"\t"+line+"\n");}File[] old=dir.listFiles((d,n)->n.startsWith("hour-")&&n.endsWith(".log"));if(old!=null)for(File file:old)try{long bucket=Long.parseLong(file.getName().substring(5,file.getName().length()-4));if(bucket<(time-3600000L)/60000)file.delete();}catch(NumberFormatException ignored){} }catch(IOException ignored){} });}
 public static void appendReport(Context c,StringBuilder b){long until=System.currentTimeMillis(),since=until-3600000;try{worker.submit(()->{}).get(10,TimeUnit.SECONDS);}catch(Exception ignored){}File[] files=new File(c.getFilesDir(),"logs").listFiles((d,n)->n.startsWith("hour-")&&n.endsWith(".log"));b.append("\n--- 最近一小时日志 ---\n");if(files==null)return;Arrays.sort(files,Comparator.comparing(File::getName));java.text.SimpleDateFormat stamp=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS",Locale.US);for(File f:files)try(BufferedReader in=new BufferedReader(new FileReader(f))){String line;while((line=in.readLine())!=null){int tab=line.indexOf('\t');if(tab<0)continue;try{long time=Long.parseLong(line.substring(0,tab));if(time>=since&&time<=until)b.append(stamp.format(new Date(time))).append("  ").append(line.substring(tab+1)).append('\n');}catch(NumberFormatException ignored){}}}catch(IOException ignored){} }
}
